import {
  Column,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { InvoiceLine } from './invoice-line.entity';
import { Organisation } from './organisation.entity';

export type InvoiceStatus =
  | 'draft'
  | 'issued'
  | 'partially_paid'
  | 'overdue'
  | 'paid'
  | 'void';

@Entity({ name: 'invoices' })
@Index(['organisationId', 'status'])
export class Invoice {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  /** Human readable number printed on the document, e.g. INV-2026-004182. */
  @Column({ unique: true, length: 32 })
  reference!: string;

  @Column({ name: 'organisation_id' })
  organisationId!: string;

  @ManyToOne(() => Organisation, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'organisation_id' })
  organisation!: Organisation;

  @Column({ type: 'varchar', length: 20, default: 'draft' })
  status!: InvoiceStatus;

  @Column({ length: 3, default: 'EUR' })
  currency!: string;

  @Column({ name: 'total_cents', type: 'int' })
  totalCents!: number;

  /** What is still outstanding after payments and credit notes. */
  @Column({ name: 'balance_cents', type: 'int' })
  balanceCents!: number;

  @Column({ name: 'issued_on', type: 'date' })
  issuedOn!: string;

  @Column({ name: 'due_on', type: 'date' })
  dueOn!: string;

  @OneToMany(() => InvoiceLine, (line) => line.invoice, { cascade: ['insert'] })
  lines!: InvoiceLine[];

  @Column({ name: 'created_at', type: 'timestamptz', default: () => 'now()' })
  createdAt!: Date;
}

