import { Controller, Get, Param, ParseUUIDPipe, UseGuards } from '@nestjs/common';
import {
  CurrentUser,
  JwtAuthGuard,
  type AuthenticatedUser,
} from '../auth/jwt-auth.guard';
import { InvoicesService, type InvoiceSummary } from './invoices.service';
import type { Invoice } from '../billing/entities/invoice.entity';

@Controller('api/invoices')
@UseGuards(JwtAuthGuard)
export class InvoicesController {
  constructor(private readonly invoices: InvoicesService) {}

  @Get()
  async list(@CurrentUser() actor: AuthenticatedUser): Promise<InvoiceSummary[]> {
    return this.invoices.listOutstanding(actor);
  }

  @Get('overdue-count')
  async overdueCount(
    @CurrentUser() actor: AuthenticatedUser,
  ): Promise<{ overdue: number }> {
    return { overdue: await this.invoices.countOverdue(actor) };
  }

  @Get(':invoiceId')
  async detail(
    @Param('invoiceId', ParseUUIDPipe) invoiceId: string,
    @CurrentUser() actor: AuthenticatedUser,
  ): Promise<Invoice> {
    return this.invoices.getInvoiceDetail(invoiceId, actor);
  }
}

