import { Controller, Get, Query, UseGuards } from '@nestjs/common';
import {
  CurrentUser,
  JwtAuthGuard,
  type AuthenticatedUser,
} from '../auth/jwt-auth.guard';
import {
  InvoiceSearchService,
  type InvoiceSearchResult,
} from './invoice-search.service';

@Controller('api/invoices')
@UseGuards(JwtAuthGuard)
export class InvoiceSearchController {
  constructor(private readonly search: InvoiceSearchService) {}

  /** Grid behind the search box in the finance console. */
  @Get('search')
  async run(
    @CurrentUser() actor: AuthenticatedUser,
    @Query('reference') reference?: string,
    @Query('taxIdentifier') taxIdentifier?: string,
    @Query('status') status?: string,
    @Query('sortBy') sortBy?: string,
    @Query('direction') direction?: string,
    @Query('page') page?: string,
  ): Promise<InvoiceSearchResult[]> {
    return this.search.search(
      {
        reference,
        taxIdentifier,
        status,
        sortBy,
        direction,
        page: Number.parseInt(page ?? '1', 10) || 1,
      },
      actor,
    );
  }
}

