import { Column, Entity, Index, PrimaryGeneratedColumn } from 'typeorm';

export type DunningStage = 'reminder' | 'first_notice' | 'final_notice' | 'collections';
export type DunningStatus = 'open' | 'paused' | 'settled' | 'written_off';

@Entity({ name: 'dunning_cases' })
@Index(['organisationId', 'stage'])
export class DunningCase {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ name: 'organisation_id' })
  organisationId!: string;

  @Column({ name: 'invoice_id' })
  invoiceId!: string;

  @Column({ name: 'invoice_reference', length: 32 })
  invoiceReference!: string;

  @Column({ name: 'debtor_name', length: 200 })
  debtorName!: string;

  @Column({ type: 'varchar', length: 20, default: 'reminder' })
  stage!: DunningStage;

  @Column({ type: 'varchar', length: 20, default: 'open' })
  status!: DunningStatus;

  @Column({ name: 'overdue_cents', type: 'int' })
  overdueCents!: number;

  @Column({ name: 'next_action_on', type: 'date' })
  nextActionOn!: string;

  @Column({ name: 'write_off_reason_code', length: 40, nullable: true })
  writeOffReasonCode!: string | null;

  @Column({ length: 500, nullable: true })
  memo!: string | null;

