import { Injectable, Logger, NotFoundException, UnprocessableEntityException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { DunningCase } from '../billing/entities/dunning-case.entity';

export interface WriteOffReceipt {
  caseId: string;
  invoiceReference: string;
  writtenOffCents: number;
  closedAt: string;
}

export interface CloseCaseInput {
  caseId: string;
  organisationId: string;
  reasonCode: string;
  memo: string;
  closedById: string;
}

@Injectable()
export class CaseWriteOffService {
  private readonly logger = new Logger(CaseWriteOffService.name);

  constructor(
    @InjectRepository(DunningCase)
    private readonly cases: Repository<DunningCase>,
  ) {}

  async close(input: CloseCaseInput): Promise<WriteOffReceipt> {
    const dunningCase = await this.cases.findOne({
      where: { id: input.caseId, organisationId: input.organisationId },
    });

    if (!dunningCase) {
      throw new NotFoundException(`Dunning case ${input.caseId} does not exist`);
    }

    if (dunningCase.status !== 'open') {
      throw new UnprocessableEntityException(
        `Case ${dunningCase.invoiceReference} is already ${dunningCase.status}`,
      );
    }

    dunningCase.status = 'written_off';
    dunningCase.writeOffReasonCode = input.reasonCode;
    dunningCase.memo = input.memo;
    dunningCase.closedById = input.closedById;
    dunningCase.closedAt = new Date();

    const saved = await this.cases.save(dunningCase);

    this.logger.warn(
      `case ${saved.invoiceReference} written off for ${saved.overdueCents} cents`,
    );

    return {
      caseId: saved.id,
      invoiceReference: saved.invoiceReference,
      writtenOffCents: saved.overdueCents,
      closedAt: (saved.closedAt ?? new Date()).toISOString(),
    };
  }
}

