import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

/**
 * Typed view over the environment. Everything the billing service needs to
 * find on disk or in another system is resolved here once at boot.
 */
@Injectable()
export class BillingConfigService {
  constructor(private readonly config: ConfigService) {}

  /** Where the month end job writes freshly rendered statements. */
  get statementRoot(): string {
    return this.config.get<string>('DOCUMENTS_STATEMENT_ROOT', '/srv/billing/statements');
  }

  /** Read only volume holding everything printed before the 2024 migration. */
  get statementArchiveRoot(): string {
    return this.config.get<string>(
      'DOCUMENTS_STATEMENT_ARCHIVE_ROOT',
      '/srv/billing/archive/statements',
    );
  }

  get creditNoteRoot(): string {
    return this.config.get<string>('DOCUMENTS_CREDIT_NOTE_ROOT', '/srv/billing/credit-notes');
  }

  get creditNoteArchiveRoot(): string {
    return this.config.get<string>(
      'DOCUMENTS_CREDIT_NOTE_ARCHIVE_ROOT',
      '/srv/billing/archive/credit-notes',
    );
  }

  get defaultCurrency(): string {
    return this.config.get<string>('BILLING_DEFAULT_CURRENCY', 'EUR');
  }

  /** Days after the due date before a dunning case opens. */
  get dunningGraceDays(): number {
    return Number(this.config.get<string>('BILLING_DUNNING_GRACE_DAYS', '5'));
  }
}

