import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Not, Repository } from 'typeorm';
import { CreditNote } from '../billing/entities/credit-note.entity';

export interface IndexedCreditNote {
  reference: string;
  storedFileName: string;
}

@Injectable()
export class CreditNoteIndexService {
  constructor(
    @InjectRepository(CreditNote)
    private readonly creditNotes: Repository<CreditNote>,
  ) {}

  /** The rendered credit note for one organisation, if the PDF exists yet. */
  async findForOrganisation(
    reference: string,
    organisationId: string,
  ): Promise<IndexedCreditNote | null> {
    const note = await this.creditNotes.findOne({
      where: { reference, organisationId, storedFileName: Not('') },
      select: { reference: true, storedFileName: true },
    });

    if (!note?.storedFileName) {
      return null;
    }

    return { reference: note.reference, storedFileName: note.storedFileName };
  }
}

